<script lang="ts">import{registerPasskey,webauthnAvailable}from'$lib/webauthn';let username=$state('');let displayName=$state('');let friendlyName=$state('This device');let submitting=$state(false);let error=$state('');async function submit(){submitting=true;error='';try{await registerPasskey(username,displayName,friendlyName);window.location.assign('/security');}catch{error='We could not create the account. Nothing was saved; please try again.';submitting=false;}}</script>
<svelte:head><title>Create account · Piquel</title></svelte:head><section><a href="/">← Sign in</a><h1>Create a passkey account</h1>{#if error}<div class="error" role="alert">{error}</div>{/if}{#if webauthnAvailable()}<form onsubmit={async(event)=>{event.preventDefault();await submit();}}><label for="username">Username</label><input id="username" bind:value={username} pattern={'[a-z0-9_]{3,32}'} autocomplete="username" required /><label for="name">Display name</label><input id="name" bind:value={displayName} maxlength="80" autocomplete="name" required /><label for="device">Passkey name</label><input id="device" bind:value={friendlyName} maxlength="80" required /><button disabled={submitting}>{submitting?'Creating passkey…':'Create account and passkey'}</button></form>{:else}<p role="alert">A passkey-capable browser in a secure context is required.</p>{/if}</section>
